class Solution:
    def generateKey(self, num1: int, num2: int, num3: int) -> int:
        res, place = 0, 1
        for _ in range(4):
            d = min(num1 % 10, num2 % 10, num3 % 10)
            res += d * place
            place *= 10
            num1 //= 10; num2 //= 10; num3 //= 10
        return res

