    int generateKey(int num1, int num2, int num3) {
        char buf[5];
        for (int i = 0; i < 4; i++) {
            int d1 = num1 % 10, d2 = num2 % 10, d3 = num3 % 10;
            buf[3 - i] = '0' + std::min({d1, d2, d3});
            num1 /= 10; num2 /= 10; num3 /= 10;
        }
        buf[4] = 0;
        return atoi(buf);
    }
};

