var generateKey = function(num1, num2, num3) {
    const pad = x => String(x).padStart(4, '0');
    const [s1, s2, s3] = [pad(num1), pad(num2), pad(num3)];
    let key = '';
    for (let i = 0; i < 4; i++)
        key += Math.min(s1[i], s2[i], s3[i]);
    return parseInt(key, 10);
